// Writes ready-to-send JSON argument files for a testnet demo from tests/vectors.json
// (a season generated by the real engine.js v2 rules with deterministic test salts).
// Usage: node scripts/demo-args.mjs [seasonIndex=0]  ->  target/demo-args/*.json
// Then: near contract call-function as-transaction <CONTRACT_ID> reveal_leaf file-args target/demo-args/reveal-0.json ...
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const dir = fileURLToPath(new URL('..', import.meta.url));
const v = JSON.parse(readFileSync(`${dir}tests/vectors.json`, 'utf8'));
const k = Number(process.argv[2] ?? 0);
const s = v.seasons[k];
if (!s) throw new Error(`no season ${k}; vectors have ${v.seasons.length}`);
const out = `${dir}target/demo-args/`;
mkdirSync(out, { recursive: true });
const put = (name, obj) => writeFileSync(out + name, JSON.stringify(obj));

put('commit-season.json', { season_id: s.seasonId, schedule_root: s.scheduleRoot, schema_version: s.schemaVersion, leaf_count: s.leafCount });
put('commit-ash-key.json', { season_id: s.seasonId, commitment: s.ashKey.commitment });
put('reveal-ash-key.json', { season_id: s.seasonId, phrase: s.ashKey.phrase, salt: s.ashKey.salt });
put('season.json', { season_id: s.seasonId });
for (const l of s.leaves) {
  put(`reveal-${l.index}.json`, { season_id: s.seasonId, index: l.index, canonical_event: l.canonicalEvent, salt: l.salt, merkle_path: l.path });
}
const bad = s.leaves[5];
put('reveal-5-tampered-salt.json', { season_id: s.seasonId, index: bad.index, canonical_event: bad.canonicalEvent, salt: (bad.salt[0] === '0' ? '1' : '0') + bad.salt.slice(1), merkle_path: bad.path });
console.log(`season ${s.seasonId} (root ${s.scheduleRoot}, ${s.leafCount} leaves) -> ${out}`);